    "question": "数据分类分级的核心目的是什么？员工在日常工作中应如何落实分类分级\n要求？",
    "options": [],
    "answer": "(1)核心目的：避免“一刀切”的保护方式，实现对不同类别、不同级\n别数据的差异化、精细化保护，在保障安全的前提下提高数据使用效率；\n(2)员工落实要求：识别本岗位接触的数据类别与级别；按对应级别遵\n守存储、传输、使用等管控要求；发现数据分级不当或保护措施不到位时\n及时反馈。"
