    "options": [],
    "answer": "“三驾马车”指《网络安全法》《数据安全法》《个人信息保护法》：\n(1)《网络安全法》：侧重网络空间整体安全，规范网络运营者行为，\n确立网络安全等级保护制度；\n(2)《数据安全法》：全面规范数据处理活动，建立数据分类分级保护、\n风险评估、出境安全评估等核心制度；\n(3)《个人信息保护法》：聚焦个人信息保护，确立告知同意、最小必\n要、个人信息出境等核心规则。"
