    "answer": "过拟合是指模型在训练数据上表现很好，但泛化能力差，在测试数据上表现\n不佳，通常因为模型过于复杂。缓解方法包括：增加训练数据、正则化、Dropout、\n早停等。欠拟合是指模型在训练数据和测试数据上表现都不好，通常因为模型过\n于简单。缓解方法包括：增加模型复杂度、增加特征、减少正则化等。"
